{
  "segment_function": "The block defines the distinction between work and labor through the concepts of homo faber, the human artifice, durability, and objectivity, contrasting the stability of man-made things with the cyclical nature of biological consumption.",
  "claims": [
    {
      "claim": "The work of our hands is distinguished from the labor of our bodies by homo faber fabricating things that constitute the human artifice, as opposed to animal laborans mixing with nature.",
      "claim_type": "author_position",
      "supporting_excerpt": "The work of our hands, as distinguished from the labor of our bodies— homo faber who makes and literally “works upon” as distinguished from the animal laborans which labors and “mixes with”—fabricates the sheer unending variety of things whose sum total constitutes the human artifice.",
      "support_kind": "direct",
      "qualifications": [],
      "confidence": 1.0
    },
    {
      "claim": "Durability gives the things of the world their relative independence and objectivity, enabling them to withstand the voracious needs and wants of their living makers and users.",
      "claim_type": "author_position",
      "supporting_excerpt": "It is this durability which gives the things of the world their relative independence from men who produced and use them, their “objectivity” which makes them withstand, “stand against” and endure, at least for a time, the voracious needs and wants of their living makers and users.",
      "support_kind": "direct",
      "qualifications": [
        "at least for a time"
      ],
      "confidence": 1.0
    }
  ],
  "definitions": [
    {
      "term": "Homo faber",
      "definition": "The maker who literally works upon materials and fabricates the things that constitute the human artifice."
    },
    {
      "term": "Animal laborans",
      "definition": "The laborer who labors and mixes with biological processes."
    }
  ],
  "distinctions": [
    {
      "item_a": "Work",
      "item_b": "Labor",
      "distinction": "Work is the activity of hands by homo faber that makes and works upon things to create a durable human artifice, whereas labor is the activity of animal laborans that mixes with biological processes."
    },
    {
      "item_a": "Use",
      "item_b": "Consumption",
      "distinction": "Destruction is inherent in consumption, whereas wear is incidental to use, as use objects possess an independence and durability that allows them to survive even when unused."
    }
  ],
  "examples": [],
  "objections": [],
  "responses": [],
  "references_to_other_sections": [],
  "unresolved_context": [],
  "must_not_be_lost": [
    "The distinction between homo faber and animal laborans.",
    "The role of durability and objectivity in stabilizing human life and identity."
  ]
}

